with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MLAC_EMI_PC_BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , PLC_BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUSTOMER_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_BANDHAN_MEDI_CLAM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bandhan_medi_clam') }}
    where (nullif(trim(CUSTOMER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSPITAL_ID))) as HUB_PARTY_HK
        , BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(HOSPITAL_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , BANK_NAME as BANK_NAME
        , NAME_BANK_ACCOUNT as ACCOUNT_HOLDER_NAME
        , BR_MICR_CODE as MICR_CODE
        , IFSC_CODE_NEFT as IFSC_CODE
        , ACCOUNT_TYPE as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_ID))) as HUB_PARTY_HK
        , BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , MICR_CODE as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(MEMBER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUSTOMER_ID))) as HUB_PARTY_HK
        , BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , BRANCH_MICR_CODE as MICR_CODE
        , BRANCH_IFSC_CODE as IFSC_CODE
        , ACCOUNT_TYPE as ACCOUNT_TYPE
        , NEFT_BANK_STATUS as ACCOUNT_STATUS
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(CUSTOMER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , cast(null as varchar) as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_NEFT_PARTNER_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_partner_dtls') }}
    where (nullif('PARTID:' || nullif(trim(PART_ID),''), 'PARTID:')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUST_ID))) as HUB_PARTY_HK
        , BANK_NAME as BANK_NAME
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , cast(null as varchar) as MICR_CODE
        , BANKIFSC as IFSC_CODE
        , cast(null as varchar) as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_STATUS
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (nullif(trim(CUST_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then BANK_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BANK_NAME end)) as BANK_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_HOLDER_NAME end) as ACCOUNT_HOLDER_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MICR_CODE end) as MICR_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then IFSC_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then IFSC_CODE end)) as IFSC_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_TYPE end) as ACCOUNT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_STATUS end) as ACCOUNT_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when BANK_NAME is not null or ACCOUNT_HOLDER_NAME is not null or MICR_CODE is not null or IFSC_CODE is not null or ACCOUNT_TYPE is not null or ACCOUNT_STATUS is not null
                     then md5(upper(coalesce(cast(BANK_NAME as varchar), '') || '|' || coalesce(cast(ACCOUNT_HOLDER_NAME as varchar), '') || '|' || coalesce(cast(MICR_CODE as varchar), '') || '|' || coalesce(cast(IFSC_CODE as varchar), '') || '|' || coalesce(cast(ACCOUNT_TYPE as varchar), '') || '|' || coalesce(cast(ACCOUNT_STATUS as varchar), '')))
                end as SAT_PARTY_BANKING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_BANKING_HASHDIFF is not null
